"""Finite rings generated by the queue handback rule.

Actual queue/controller consumption is transferred through shared capture
snapshots, independently from data completion. Window membership describes
parametric uses including outer reentry; a finite upper bound can instead give
one ID per use. Numbering consumes these established facts without new queries.
"""

from dataclasses import dataclass
from functools import cached_property

from ..diagnostics import CompileError, ErrorKind, require
from ..memo import memoized_method
from ..scalar import Expr, expression, literal, substitute
from ..symbols import Symbol, SymbolKind
from .consumption_frontiers import AcquiredConsumption, ConsumptionFrontiers
from .event_contracts import CROSS_BACKLOG, LOCAL_CAPACITY, CaseLease, StructuredEventLease
from .protocol_transfers import (
    CausalProof,
    ConsumptionOrigin,
    ProtocolPositions,
    ProtocolTransfers,
    TransferNode,
)
from .structured_protocols import NotificationKind
from .structured_schedule import ActionGuard, Comparison


@dataclass(frozen=True, slots=True)
class Handback:
    consume: object
    next_set: object
    condition: ActionGuard
    proof: object


@dataclass(frozen=True, slots=True)
class ConsumptionDerivation:
    origin: ConsumptionOrigin
    target: object
    proof: CausalProof
    answer: object


@dataclass(frozen=True, slots=True)
class Reuse:
    loop: object | None
    # None denotes every positive gap, with independent later coordinates.
    delta: int | None
    upper_uses: int | None
    condition: ActionGuard
    handbacks: tuple[Handback, ...] = ()


class HandbackRule:
    def __init__(self, domains):
        self.domains = domains
        self.peers = tuple(
            n for n in domains.notifications if n.mechanism is not NotificationKind.PIPE_FENCE
        )
        self.positions = ProtocolPositions(domains)
        self.boundary_cases = {}
        self.invocation_boundaries = {}
        self.declined_boundaries = {}
        self._consumptions = {}

    @cached_property
    def frontiers(self):
        return ConsumptionFrontiers(self.domains, self.positions)

    @memoized_method
    def single_case(self, notification):
        domains = self.domains
        cases = domains.cases[notification]
        if len(cases) != 1 or cases[0].empty or cases[0].windows:
            return None
        case = cases[0]
        root = domains.memory.module.body.block.first_op
        for point in notification.sources + notification.consumers:
            if any(not domains.control.invariant_over(v, root) for _, v in point.coordinates):
                return None
            instance = domains._instance(point, {}, case=case)
            if any(
                not domains.control.invariant_over(t.lhs, root)
                or not domains.control.invariant_over(t.rhs, root)
                for t in instance.guard.comparisons
            ):
                return None
        return case

    @memoized_method
    def _translated_stream(self, notification, *, consumer_families=False):
        """Canonical clocks advance the real sites by unit translations.

        Selected child FIRST/LAST coordinates are allowed only when independent
        of that child clock. Reversed or mixed coordinate maps are not episodes.
        """
        domains = self.domains
        clocks = domains.clocks[notification]
        if not clocks:
            return False
        for point in notification.sources + notification.consumers:
            if point.families and (not consumer_families or point in notification.sources):
                return False
            actual = dict(point.coordinates)
            for loop in clocks:
                if loop not in actual:
                    return False
                shift = domains.arithmetic.normalize(
                    expression("sub", actual[loop], domains.control.loops[loop].ordinal)
                )
                if not domains.control.invariant_over(shift, loop):
                    return False
            if any(
                not domains.control.invariant_over(value, loop)
                for loop, value in point.coordinates
                if loop not in clocks
            ):
                return False
        return True

    def ordered_stream(self, notification, case):
        return tuple(w.loop for w in case.windows) == self.domains.clocks[
            notification
        ] and self._translated_stream(notification)

    def _cases(self, peer):
        cases = self.domains.cases[peer]
        if self.domains.clocks[peer] and not any(c.windows for c in cases):
            if peer not in self.boundary_cases:
                from .event_families import build_event_family

                # Cell credits need no dense ordinal. A streaming caller can
                # additionally require exact invocation boundary membership.
                # Universal pairing survives this domain specialization.
                try:
                    if peer in self.domains._window_errors:
                        raise self.domains._window_errors[peer]
                    cases = build_event_family(self.domains, peer)
                except CompileError as error:
                    if error.kind is not ErrorKind.UNSUPPORTED or error.phase not in {
                        "event-parameter-cases",
                        "event-window-membership",
                    }:
                        raise
                    # This is optional relay precision, not the peer's own
                    # pairing/lifetime. An unavailable exact child boundary
                    # supplies no handback. Required channels are never
                    # removed and must still acquire a complete lease.
                    self.declined_boundaries[peer] = error
                    self.domains.work.optional_relay_declines += 1
                    cases = ()
                self.boundary_cases[peer] = cases
            return self.boundary_cases[peer]
        return cases

    def _child_cases(self, peer, scope):
        """Optional child ports do not require a rank across parent calls."""
        cases = self._cases(peer)
        if cases:
            return cases
        key = peer, scope
        if key not in self.invocation_boundaries:
            from .event_families import build_boundary_family

            try:
                cases = build_boundary_family(self.domains, peer, scope)
            except CompileError as error:
                if error.kind is not ErrorKind.UNSUPPORTED or error.phase not in {
                    "event-parameter-cases",
                    "event-window-membership",
                }:
                    raise
                self.declined_boundaries[peer] = error
                self.domains.work.optional_relay_declines += 1
                cases = ()
            self.invocation_boundaries[key] = cases
        return self.invocation_boundaries[key]

    @memoized_method
    def _step(self, bound, loop):
        d = self.domains
        task = d.dispatch.site(bound)
        scope, stage = task.scope, task.stage
        while scope.operation is not loop and scope.parent is not None:
            stage, scope = scope.parent_stage, scope.parent
        if scope.operation is not loop:
            return None
        coordinate = dict(bound.coordinates).get(loop)
        if coordinate is None:
            return None
        return d.arithmetic.normalize(
            expression(
                "sub", expression("add", coordinate, literal(stage)), d.control.loops[loop].ordinal
            )
        ).constant

    @memoized_method
    def _region_transfer(self, loop, begin, end, queue_composition):
        """Share one finite invocation boundary across all unchanged origins.

        FIRST/LAST are the established window ports, never runtime expansion.
        The offset horizon is the actual local stage span of this reuse case.
        """
        d = self.domains

        def episodes():
            seen = set()
            for peer in self.peers:
                if loop is None:
                    offsets = (0,)
                elif loop in d.clocks[peer]:
                    starts = [self._step(p, loop) for p in peer.sources]
                    stops = [self._step(p, loop) for p in peer.consumers]
                    if begin is None or end is None or any(v is None for v in starts + stops):
                        continue
                    offsets = range(begin - max(starts), end - min(stops) + 1)
                else:
                    offsets = (0,)
                for case in self._child_cases(peer, loop):
                    if case.empty:
                        continue
                    for offset in offsets:
                        for last in (False, True):
                            sources, consumers = d._boundary(peer, case, loop, offset, last=last)
                            key = peer, sources, consumers
                            if key in seen:
                                continue
                            seen.add(key)
                            d.work.consumption_instances += 1
                            yield peer, case, sources, consumers

        d.work.consumption_regions += 1
        return ProtocolTransfers(
            d, episodes(), positions=self.positions, native_composition=not queue_composition
        )

    @staticmethod
    def _handback(origin, target, proof, answer, assumptions):
        return (
            Handback(
                origin.point,
                target,
                ActionGuard(assumptions),
                ConsumptionDerivation(origin, target, proof, answer),
            ),
        )

    def establish(
        self,
        channel,
        old,
        target_channel,
        target,
        assumptions,
        *,
        loop,
        queue_composition=True,
    ):
        d = self.domains
        assumptions = tuple(
            dict.fromkeys(assumptions + d._input_ranges(old) + d._input_ranges(target))
        )
        key = (
            channel,
            old,
            target,
            target_channel.source_engine,
            assumptions,
            loop,
            queue_composition,
        )
        if key in self._consumptions:
            d.work.consumption_fact_reuses += 1
            return self._consumptions[key]
        result = self._establish(
            channel, old, target, target_channel.source_engine, assumptions, loop, queue_composition
        )
        if result is not None:
            self._consumptions[key] = result
        return result

    def _establish(self, channel, old, target, engine, assumptions, loop, queue_composition):
        d = self.domains
        origin = ConsumptionOrigin(old, channel)
        condition = False
        if old.actor is target.actor and (d._gate(channel) or channel.destination_engine is engine):
            condition = self.positions.order(old, target, strict=True)
        d.work.handback_cover_queries += 1
        answer = d.arithmetic.queries.implies(condition, assumptions)
        if answer.proved:
            proof = CausalProof(
                TransferNode("consume-admission", None, target, (), condition), (), condition
            )
            queue_composition = False
        else:
            established = self.frontiers.find(
                origin, target, engine, assumptions, queue_composition=queue_composition
            )
            if established is not None:
                proof, answer = established
            else:
                begin = None if loop is None else self._step(old, loop)
                end = None if loop is None else self._step(target, loop)
                graph = self._region_transfer(loop, begin, end, queue_composition)
                proof = graph.consumption(channel, old, target, engine, assumptions=assumptions)
                if proof is None:
                    return None
                d.work.handback_cover_queries += 1
                answer = d.arithmetic.queries.implies(proof.condition, assumptions)
                if not answer.proved:
                    return None
                self.frontiers.add_acquisitions(
                    origin, assumptions, proof, queue_composition=queue_composition
                )
        self.frontiers.add(
            AcquiredConsumption(
                origin,
                target,
                engine,
                assumptions,
                proof,
                answer,
                queue_composition=queue_composition,
            )
        )
        return self._handback(origin, target, proof, answer, assumptions)

    def reuse(self, channel, case, window, width, *, reentry, queue_composition=True):
        d, loop = self.domains, window.loop
        ordinal = d.control.loops[loop].ordinal
        result = []
        for phase, delta in window.reuse_phases(width):
            if reentry:
                old_sources, old_waits = d._boundary(channel, case, loop, 0, last=True)
                next_sources, next_waits = d._boundary(channel, case, loop, delta, last=False)
            else:
                shifted = {ordinal: expression("add", ordinal, literal(delta))}
                old_sources = tuple(d._instance(p, {}, case=case) for p in channel.sources)
                old_waits = tuple(d._instance(p, {}, case=case) for p in channel.consumers)
                next_sources = tuple(d._instance(p, shifted, case=case) for p in channel.sources)
                next_waits = tuple(d._instance(p, shifted, case=case) for p in channel.consumers)
            condition = ActionGuard(
                tuple(dict.fromkeys(case.condition.comparisons + phase.comparisons))
            )
            assumptions = tuple(
                dict.fromkeys(
                    condition.comparisons
                    + tuple(
                        t
                        for p in old_sources + old_waits + next_sources + next_waits
                        for t in p.guard.comparisons
                    )
                )
            )
            handbacks = []
            for old in old_waits:
                for target in next_sources:
                    rule = self.establish(
                        channel,
                        old,
                        channel,
                        target,
                        assumptions,
                        loop=loop,
                        queue_composition=queue_composition,
                    )
                    if rule is None:
                        return None
                    handbacks.extend(rule)
            result.append(Reuse(loop, delta, None, condition, tuple(handbacks)))
        return tuple(result)

    def _uses(self, channel, case, window, width, *, reentry, queue_composition):
        if window.upper is not None and window.upper <= width:
            return (Reuse(window.loop, 0, window.upper, case.condition),)
        return self.reuse(
            channel,
            case,
            window,
            width,
            reentry=reentry,
            queue_composition=queue_composition,
        )

    @staticmethod
    def _case_lease(case, rings, uses, *, cross, policy):
        width, ordinal = 1, literal(0)
        for window, ring in rings:
            width *= ring
            local = (
                literal(0)
                if window.single or ring == 1
                else expression("rem", window.rank(), literal(ring))
            )
            ordinal = expression("add", expression("mul", ordinal, literal(ring)), local)
        return CaseLease(
            case,
            1 if cross else width,
            ordinal,
            tuple(rings),
            tuple(uses[-1]) if uses else (Reuse(None, 0, 1, case.condition),),
            tuple(r for group in uses[:-1] for r in group),
            width if cross else None,
            policy,
        )

    def case(self, channel, case):
        """Preferred protocol: finite uses and native-boundary handbacks.

        Later queue-composition knowledge is an optional resource premise.
        It must not silently choose a narrower ring for an accepted preferred
        protocol. A failed whole case may require smaller earlier dimensions;
        retry once with queue-composition allowed throughout. The resource
        planner separately requests optional changes to accepted protocols.
        """
        d = self.domains
        d.work.ring_cases += 1
        cross = channel.mechanism is NotificationKind.CROSS_EVENT
        capacity = CROSS_BACKLOG if cross else LOCAL_CAPACITY
        proofs = {}

        def construct(modes):
            width, rings, uses = 1, [], []
            policy = "native-handback"
            for index in reversed(range(len(case.windows))):
                window = case.windows[index]
                for queue_composition in modes:
                    proof = None
                    for candidate in range(1, capacity // width + 1):
                        key = index, candidate, queue_composition
                        if key not in proofs:
                            proofs[key] = self._uses(
                                channel,
                                case,
                                window,
                                candidate,
                                reentry=index < len(case.windows) - 1,
                                queue_composition=queue_composition,
                            )
                        proof = proofs[key]
                        if proof is not None:
                            break
                    if proof is not None:
                        if queue_composition:
                            policy = "required-queue-handback"
                        break
                else:
                    return None
                width *= candidate
                rings.insert(0, (window, candidate))
                uses.insert(0, proof)
            return self._case_lease(case, rings, uses, cross=cross, policy=policy)

        preferred = construct((False, True))
        if preferred is not None:
            return preferred
        # A dimension's handback depends on its real endpoints and width,
        # never the other ring digits. Their independently smallest proved
        # widths minimize the product, without a Cartesian protocol search.
        required = construct((True,))
        if required is not None:
            return required
        d.fail(
            channel,
            "queue handback rule cannot establish consumption before reuse within event capacity",
            phase="notification-generation-lifetime",
            witness=tuple(
                f"optional relay {n.name}: {e.phase}" for n, e in self.declined_boundaries.items()
            ),
        )

    def smaller_lease(self, lease):
        """One finite, monotonically smaller option; no ring Cartesian product.

        Change a dimension only with its own complete handback. Unchanged
        dimensions retain their original facts, including outer reentry.
        Optional queue relays never insert or move an instruction.
        """
        channel, cases = lease.notification, []
        cross = channel.mechanism is NotificationKind.CROSS_EVENT
        for old in lease.cases:
            rings = list(old.rings)
            uses = [
                tuple(r for r in (*old.reentries, *old.inside) if r.loop is window.loop)
                for window, _ in rings
            ]
            for index in reversed(range(len(rings))):
                window, width = rings[index]
                for candidate in range(1, width):
                    proof = self._uses(
                        channel,
                        old.case,
                        window,
                        candidate,
                        reentry=index < len(rings) - 1,
                        queue_composition=True,
                    )
                    if proof is not None:
                        rings[index] = window, candidate
                        uses[index] = proof
                        break
            cases.append(
                old
                if tuple(rings) == old.rings
                else self._case_lease(old.case, rings, uses, cross=cross, policy="resource-shrink")
            )
        return StructuredEventLease(channel, max((c.width for c in cases), default=0), tuple(cases))

    def lease(self, notification):
        if any(
            not c.empty and not c.windows and self.domains.clocks[notification]
            for c in self.domains.cases[notification]
        ):
            result = self._sparse_local_lease(notification)
            if result is not None:
                return result
            if notification in self.domains._window_errors:
                raise self.domains._window_errors[notification]
        require(
            all(
                tuple(window.loop for window in c.windows) == self.domains.clocks[notification]
                for c in self.domains.cases[notification]
                if self.domains.active[notification, c]
            ),
            "queue handback needs exact membership for every common clock",
            kind=ErrorKind.UNSUPPORTED,
            phase="notification-generation-lifetime",
        )
        cases = tuple(
            self.case(notification, c)
            for c in self.domains.cases[notification]
            if self.domains.active[notification, c]
        )
        return StructuredEventLease(notification, max((c.width for c in cases), default=0), cases)

    def _sparse_local_lease(self, channel):
        """One binary flag when every later publication follows consumption.

        Partition two arbitrary uses by their first differing common clock.
        That clock advances by 1+gap, gap>=0; descendant coordinates are fresh.
        Earlier coordinates remain equal. This covers all strictly ordered
        uses, including empty gaps and nested reentry, without dense ranks.
        The channel is excluded from each retained-action consumption proof.
        """
        d = self.domains
        cases = d.cases[channel]
        if (
            channel.mechanism is not NotificationKind.LOCAL_EVENT
            or len(channel.sources) != 1
            or len(channel.consumers) != 1
            or channel.sources[0].actor is not channel.consumers[0].actor
            or len(cases) != 1
            or cases[0].windows
            or not self._translated_stream(channel, consumer_families=True)
        ):
            return None
        case = cases[0]
        if not d.active[channel, case]:
            return StructuredEventLease(channel, 0, ())
        lease = self._sparse_local_ring(channel, case, 1, literal(0))
        if lease is not None:
            return lease
        # Sparse parent calls need no dense rank. A real descendant clock can
        # name finite lanes if every pair of actual uses of the same lane has
        # a consumption handback, including parent reentry and empty gaps.
        phase = d.control.loops[d.clocks[channel][-1]].ordinal
        for width in range(2, LOCAL_CAPACITY + 1):
            lease = self._sparse_local_ring(channel, case, width, phase)
            if lease is not None:
                return lease
        return None

    def _sparse_local_ring(self, channel, case, width, phase):
        d = self.domains
        source, wait = (
            d._instance(p, {}, case=case) for p in (channel.sources[0], channel.consumers[0])
        )
        clocks, uses = d.clocks[channel], []
        for index, loop in enumerate(clocks):
            ordinal = d.control.loops[loop].ordinal
            gap = Expr("argument", (Symbol("$reuse_gap", SymbolKind.ORDINAL, object()),))
            shifted = {ordinal: expression("add", expression("add", ordinal, literal(1)), gap)}
            for child in clocks[index + 1 :]:
                coordinate = d.control.loops[child].ordinal
                shifted[coordinate] = Expr(
                    "argument", (Symbol("$reuse_next", SymbolKind.ORDINAL, object()),)
                )
            next_source, next_wait = (
                d._instance(p, shifted, case=case)
                for p in (channel.sources[0], channel.consumers[0])
            )
            condition = ActionGuard((Comparison(gap, ">=", literal(0)),))
            if width > 1:
                condition = ActionGuard(
                    condition.comparisons
                    + (
                        Comparison(
                            expression("rem", phase, literal(width)),
                            "==",
                            expression("rem", substitute(phase, shifted), literal(width)),
                        ),
                    )
                )
            assumptions = tuple(
                dict.fromkeys(
                    condition.comparisons
                    + tuple(
                        test
                        for p in (source, wait, next_source, next_wait)
                        for test in (*p.guard.comparisons, *d._input_ranges(p))
                    )
                )
            )
            if d.arithmetic.queries.satisfies(assumptions).impossible:
                uses.append(Reuse(loop, None, 1, condition))
                continue
            begin, end = self._step(wait, loop), self._step(source, loop)
            if begin is None or end is None:
                return None
            # A width-lane ring can use the retained returns up to its next
            # possible same-lane publication. The later target may be
            # arbitrarily far away; exact queue order must bridge that gap.
            # This is a finite proof horizon, never runtime loop expansion.
            graph = self._region_transfer(loop, begin, max(begin, end + width), True)
            proof = graph.consumption(
                channel, wait, next_source, channel.source_engine, assumptions=assumptions
            )
            if proof is None:
                return None
            answer = d.arithmetic.queries.implies(proof.condition, assumptions)
            if not answer.proved:
                return None
            handbacks = self._handback(
                ConsumptionOrigin(wait, channel), next_source, proof, answer, assumptions
            )
            uses.append(Reuse(loop, None, None, condition, handbacks))
        lease = CaseLease(
            case,
            width,
            phase,
            (),
            tuple(uses[-1:]),
            tuple(uses[:-1]),
            policy="ordered-local-handback",
        )
        return StructuredEventLease(channel, width, (lease,))
